"""READ-ONLY. ВІДСКОК: чому 2026 рік у мінусі — пошук умови, що відрізняє невдалі серії (27.11.2026, прохання власниці).
Сигнали: дно ≥1 тесту + падіння >20% + BTC підтвердив (те, що надсилається), з data/bounce_feat_wide.csv.gz. Ціль 3R, комісія 0,10%, ризик $10.
ГІПОТЕЗИ ЗАПИСАНО ДО ПЕРЕГЛЯДУ ЦИФР (ГІПОТЕЗА):
 H1 великий тренд: вчорашнє денне закриття BTC вище / нижче середньої за 200 діб (U).
 H2 «запобіжник»: результат попередньої пачки — усі такі сигнали по ринку за 2–7 діб ДО цього (їхній підсумок уже відомий): у мінусі / у плюсі / пачки не було.
 H3 котра хвиля: скільки ДНІВ із такими сигналами по ринку вже було за попередні 7 діб: 0 / 1 / 2+.
 H4 розмір пачки: скільки таких сигналів по ринку за цю саму годину: 1–2 / 3–9 / 10+.
 H5 спроба по монеті (A): перша–третя / 4-та+.   H6 попередня спроба по монеті (P): стоп / не стоп.
 H7 RSI у дні (I): <20 / 20–30 / >30.   H8 обсяг (V): <2× / 2–4× / 4×+.   H9 весь ринок (B): так / ні.
Перевірка: 72 монети по періодах P1/P2/P3 і окремо 2026; незалежна група — 135 монет «широкої групи» (W). Умова зараховується, якщо краща частина плюсова в P1, P2, P3 і у W, а гірша — слабша в усіх.
Використання: bounce_2026.py FEAT_WIDE_CSV_GZ"""
import sys
import numpy as np, pandas as pd
E = pd.read_csv(sys.argv[1]); E = E[(E.K >= 1) & (E.F == 2) & (E["T"] == 1)].sort_values("te").reset_index(drop=True)
E["dt"] = pd.to_datetime(E.te, unit="s"); E["y"] = E.dt.dt.year; E["day"] = (E.te // 86400).astype(int); te = E.te.to_numpy(); usd = E.usd.to_numpy(); day = E.day.to_numpy()
cs = np.r_[0, np.cumsum(usd)]; lo = np.searchsorted(te, te - 7 * 86400, side="left"); hi = np.searchsorted(te, te - 2 * 86400, side="right"); prev = cs[hi] - cs[lo]; npv = hi - lo
E["H2"] = np.where(npv == 0, "пачки не було", np.where(prev < 0, "попередня пачка в мінусі", "попередня пачка в плюсі"))
ud = np.unique(day); E["H3"] = [min(2, int(((ud < d) & (ud >= d - 7)).sum())) for d in day]; E["H3"] = E.H3.map({0: "перша хвиля за тиждень", 1: "друга", 2: "третя і далі"})
hr = E.groupby("te").usd.transform("size"); E["H4"] = np.where(hr <= 2, "1–2 монети", np.where(hr <= 9, "3–9 монет", "10+ монет"))
E["H1"] = E.U.map({1: "BTC вище 200-денної", 0: "BTC нижче 200-денної", -1: "?"}); E["H5"] = np.where(E.A >= 3, "4-та+ спроба", "1–3 спроба"); E["H6"] = E.P.map({0: "не було", 1: "попередня — стоп", 2: "попередня — не стоп"})
E["H7"] = E.I.map({0: "RSI <20", 1: "RSI 20–30", 2: "RSI >30"}); E["H8"] = E.V.map({0: "обсяг <2×", 1: "обсяг 2–4×", 2: "обсяг 4×+", -1: "?"}); E["H9"] = E.B.map({1: "весь ринок: так", 0: "весь ринок: ні", -1: "?"})
M = E[E.grp.isin(["S", "C"])]; W = E[E.grp == "W"]
print(f"сигналів: 72 монети {len(M)} (${M.usd.sum():+.0f}); широка група {len(W)} (${W.usd.sum():+.0f}). 2026 на 72 монетах: {len(M[M.y==2026])} (${M[M.y==2026].usd.sum():+.0f})")
def cell(x): return f"{x.usd.mean():+6.2f} ({len(x):4d})" if len(x) else "   —        "
print(f"\n{'':32s} {'P1 2020–21':>13s} | {'P2 2022–23':>13s} | {'P3 2024–26':>13s} || {'лише 2026':>13s} || {'широка група':>13s} || сума 72 монети")
for h in ("H1", "H2", "H3", "H4", "H5", "H6", "H7", "H8", "H9"):
    print(h)
    for v, g in M.groupby(h):
        print(f"   {str(v):29s} {cell(g[g.P_=='P1'])} | {cell(g[g.P_=='P2'])} | {cell(g[g.P_=='P3'])} || {cell(g[g.y==2026])} || {cell(W[W[h]==v])} || {g.usd.sum():+7.0f}")
print("\nH2 по роках (72 монети): сума $ (кількість)")
for v, g in M.groupby("H2"): print(f"   {v:26s} " + ", ".join(f"{int(k)}: {z.usd.sum():+.0f} ({len(z)})" for k, z in g.groupby("y")))
print("H3 по роках:")
for v, g in M.groupby("H3"): print(f"   {v:26s} " + ", ".join(f"{int(k)}: {z.usd.sum():+.0f} ({len(z)})" for k, z in g.groupby("y")))
print("\n2026, дні з сигналами (72 монети): дата, сигналів, сума $, H1, H2, H3")
for d, g in M[M.y == 2026].groupby("day"): print(f"   {g.dt.iloc[0].date()}  n={len(g):2d}  {g.usd.sum():+6.0f}   {g.H1.iloc[0]:22s} {g.H2.iloc[0]:26s} {g.H3.iloc[0]}")
